"""Render the catalog's summary (summarize-catalog.py) as self-contained HTML reports.

    render-catalog.py [--dir DIR]    reads DIR/summary.json, writes DIR/overview.html and
                                     DIR/policy-coverage.html
"""
import argparse
from pathlib import Path
import json
from html import escape
from license_headers import licensed_html
ROOT = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
parser.add_argument('--dir', type=Path, default=ROOT / 'target/validation/catalog')
DIR = parser.parse_args().dir
data = json.loads((DIR / 'summary.json').read_text())
jdks = list(data['junit'])
jdk_text = ', '.join(jdks[:-1]) + ' and ' + jdks[-1] if len(jdks) > 1 else jdks[0]
controlled = f"{data['controlled'][0]['passed']} × {len(data['controlled'])}" if data['controlled'] else '0'
html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KMIP catalog evidence</title><style>
:root{font-family:system-ui,sans-serif;color:var(--foreground,#182b39);background:transparent;line-height:1.45}body{max-width:1160px;margin:0;padding:0}h1{font-size:27px;margin:0 0 8px}h2{font-size:18px;margin-top:28px}p{color:var(--muted-foreground,#4a5e6a);max-width:1000px}a{color:#185c9b}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.metric{background:var(--muted,#eef4f6);padding:16px;border-radius:9px}.metric b{font-size:25px;display:block}.metric span{font-size:12px;color:var(--muted-foreground,#476171)}.notice{border-left:4px solid #c47b20;background:var(--warning-surface,#fff8eb);padding:12px 16px;font-size:14px}.filters{display:flex;gap:12px;flex-wrap:wrap;margin:14px 0}label{font-size:12px;color:var(--muted-foreground,#526a79);display:flex;flex-direction:column;gap:5px}select,input{font:inherit;color:var(--foreground,#182b39);background:transparent;border:1px solid #bccdd6;border-radius:6px;padding:7px 10px;min-width:135px}input{min-width:240px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #dae5eb;vertical-align:top}th{color:var(--muted-foreground,#526a79);font-weight:600;font-size:11px;text-transform:uppercase}tr.selected{background:var(--accent-surface,#edf5ff)}button{font:inherit;border:0;background:none;text-align:left;padding:0;color:#185c9b;cursor:pointer}.scroll{overflow:auto;max-height:530px}thead{position:sticky;top:0;background:var(--background,#fff)}code{font-size:12px}small,.muted{color:var(--muted-foreground,#586e7c)}.PASS{color:var(--success,#127047)}.FAIL_SERVER,.FAIL_CLIENT{color:var(--destructive,#ae352c)}.BLOCKED_ENV{color:var(--warning,#98630d)}.UNSUPPORTED_SERVER{color:var(--chart-4,#704897)}.NOT_APPLICABLE{color:var(--muted-foreground,#63727b)}.badge{font-size:10px;font-weight:650;white-space:nowrap}.num{text-align:right}.reason{min-width:230px;max-width:500px}.footer{font-size:12px;overflow-wrap:anywhere}details{background:var(--muted,#f2f6f8);padding:12px 16px;border-radius:8px;margin-top:20px}summary{cursor:pointer;font-weight:600}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:11px;margin:10px 0}.layer{font-size:11px;color:var(--muted-foreground,#526a79)}#tuple-title{margin-bottom:4px}@media(max-width:650px){body{padding:0}.metrics{grid-template-columns:repeat(2,1fr)}h1{font-size:23px}.metric{padding:12px}input{min-width:200px}}
</style></head><body><h1>KMIP interoperability catalog</h1><p>Measured execution of the Keytend catalog suite on JDK JDK_TEXT. Protocols 1.1–1.4, 2.0, 2.1 and 3.0 CSD02. Synthetic test objects and verified mTLS throughout.</p>
<div class="metrics"><div class="metric"><b>CASECOUNT</b><span>catalog case identities</span></div><div class="metric"><b id="tuple-count">-</b><span>live build/version/runtime tuples</span></div><div class="metric"><b>CONTROLLED</b><span>controlled client scenarios passed</span></div><div class="metric"><b id="failures">, </b><span>client failures in final matrix</span></div></div>
<div class="notice"><b>Client assertions passed on JDK JDK_TEXT.</b> Server failures are kept as unreviewed peer observations and never count as client passes. The policy cases are covered across configured supporting fixtures. Unsupported operations and other unrun P0 prerequisites limit full server qualification. Controlled peer evidence is separate. <span id="qualified">, </span></div>
<h2>Live server matrix</h2><div class="filters"><label>Runtime<select id="jdk"><option value="">All JDKs</option><option>17</option><option>21</option><option>25</option></select></label><label>Server<select id="server"><option value="">All servers</option></select></label></div>
<div style="overflow:auto"><table><thead><tr><th>Server / build</th><th>KMIP</th><th>JDK</th><th class="num">Pass*</th><th class="num">Peer observations</th><th class="num">Unrun</th><th class="num">Unsupported</th><th class="num">Outside scope</th></tr></thead><tbody id="matrix"></tbody></table></div>
<p class="footer">*Pass counts include distinct live, fault-proxy, database-consumer and harness-inspection checks. Select a tuple to inspect the execution layer and reason for each case. JDK 17 runs every listed protocol/build; 21/25 use representative catalog tuples. The original 11 complete live workflows still run on every JDK.</p>
<h2 id="tuple-title">Case details</h2><p id="evidence" class="footer"></p><div class="filters"><label>Outcome<select id="outcome"><option value="">All outcomes</option></select></label><label>Find case<input id="search" placeholder="ID, title or reason"></label></div><div class="legend" id="legend"></div><div class="scroll"><table><thead><tr><th>Case</th><th>Outcome</th><th>Execution layer</th><th>Reason</th><th class="num">ms</th></tr></thead><tbody id="cases"></tbody></table></div><p id="shown" class="footer"></p>
<h2>Policy case coverage</h2><p class="footer">A case is covered when exercised on every configured supporting fixture and selected runtime/version. Other fixture limitations do not block aggregate SDK coverage. Coverage records execution; server correctness remains a separate result.</p><div style="overflow:auto"><table><thead><tr><th>Case</th><th>Supporting fixtures</th><th>Executed tuples</th><th>Coverage</th><th>Observed outcomes</th></tr></thead><tbody id="policy-coverage"></tbody></table></div><details><summary>Scope and reproducibility</summary><p>PyKMIP and Krypton are Apache-2.0, and PQCToday is AGPL-3.0-only. Krypton runs production KMIP handlers with fixed fixture metadata and one provisioned key; it does not qualify the full administrative deployment. KMIP 3.0 is the pinned CSD02 draft.</p><p>H2 tests use actual encrypted files, restart, backup/restore and envelope encryption. H2 derives its AES-128 file key from a password containing retrieved KMIP material. Certificate tests use actual JSSE handshakes and listener rotation. Independent Python probes and JCE checks verify key material and cryptographic results.</p><p>Native certificate chain, revocation, CA rotation and durable restart adapters are enabled. A pinned previous SDK checkpoint is tested independently. Local-fixture Get latency is qualified against the agreed p95 ≤ 1,000 ms and p99 ≤ 2,000 ms limits. The policy scenarios are covered on their supporting fixtures. Additional native policy adapters may extend that scope; completion of the 24-hour soak remains a prerequisite for that separate endurance case. Controlled CRL and TLS tests are never substituted for vendor evidence.</p><p>Per-fixture unrun records are listed below. Missing policy adapters on other fixtures do not block the aggregate policy coverage shown above.</p><ul id="blocked-reasons"></ul><p>Run <code>./integration/run.sh</code> or <code>./tools/verify-jdks.sh -Pintegration</code>. Both build the fixtures from source. Add <code>-Dkmip.catalog.exhaustive=true</code> for every catalog version on every JDK, or <code>-Dkmip.catalog.strict=true</code> to fail incomplete P0 qualification.</p><p>Full records are deterministic gzip JSON in <code>results/</code> beside this page; <code>cases.csv</code> is a flat export. Each record includes source/configuration identity, providers, TLS, timing and evidence. See <code>docs/catalog.md</code> for adapters, blocked prerequisites and external-runner instructions.</p></details>
<p class="footer" id="source"></p><script>
const D=DATA;let selected=D.tuples.findIndex(t=>t.server==='pykmip'&&t.jdk===25);const $=s=>document.querySelector(s);const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#policy-coverage').innerHTML=D.policy_coverage.map(p=>`<tr><td><b>${e(p.test_id)}</b></td><td>${e(p.supporting_fixtures.join(', '))}</td><td class="num">${p.executed_tuples}</td><td class="PASS">${e(p.coverage)}</td><td>${e(Object.entries(p.outcomes).map(([o,n])=>`${n} ${outcomeLabel(o)}`).join('; '))}</td></tr>`).join('');
$('#tuple-count').textContent=D.tuples.length;$('#failures').textContent=D.tuples.reduce((n,t)=>n+(t.outcomes.FAIL_CLIENT||0),0);const q=D.tuples.filter(t=>t.qualification.qualified).length;$('#qualified').textContent=`${q} of ${D.tuples.length} server tuples fully P0-qualified.`;
[...new Set(D.tuples.map(t=>t.server))].forEach(s=>$('#server').add(new Option(s,s)));D.states.forEach(s=>{$('#outcome').add(new Option(outcomeLabel(s),s));$('#legend').insertAdjacentHTML('beforeend',`<span class="${s}">${e(outcomeLabel(s))}</span>`)});
function outcomeLabel(s){return({FAIL_SERVER:'Unconfirmed peer observation',FAIL_CLIENT:'Client failure',BLOCKED_ENV:'Unrun on this fixture'})[s]||s}
function matrix(){let tuples=D.tuples.map((t,i)=>[t,i]).filter(([t])=>(!$('#jdk').value||t.jdk==$('#jdk').value)&&(!$('#server').value||t.server==$('#server').value));if(!tuples.some(([,i])=>i===selected)&&tuples.length)selected=tuples[0][1];$('#matrix').innerHTML=tuples.map(([t,i])=>`<tr class="${i===selected?'selected':''}"><td><button data-index="${i}">${e(t.server)} <small>${e(t.build.length>12?t.build.slice(0,12):t.build)}</small></button></td><td>${e(t.version)}${t.version==='3.0'?' draft':''}</td><td>${t.jdk}</td><td class="num PASS">${t.outcomes.PASS||0}</td><td class="num FAIL_SERVER">${t.outcomes.FAIL_SERVER||0}</td><td class="num BLOCKED_ENV">${t.outcomes.BLOCKED_ENV||0}</td><td class="num UNSUPPORTED_SERVER">${t.outcomes.UNSUPPORTED_SERVER||0}</td><td class="num NOT_APPLICABLE">${t.outcomes.NOT_APPLICABLE||0}</td></tr>`).join('');$('#matrix').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=+b.dataset.index;matrix()});cases()}
function cases(){const t=D.tuples[selected];$('#tuple-title').textContent=`${t.server} · KMIP ${t.version} · JDK ${t.jdk}`;$('#evidence').innerHTML=`${e(t.build)} · <a href="${e(t.evidence)}">Full JSON evidence (.gz)</a> · ${t.cleanup_remaining} run-owned IDs remaining before fresh container removal${t.get_latency?.outcome==='PASS'?` · Get p95 ${t.get_latency.p95_ms.toFixed(3)} ms / p99 ${t.get_latency.p99_ms.toFixed(3)} ms (limits 1,000 / 2,000 ms)`:t.get_latency?` · Get latency: ${e(outcomeLabel(t.get_latency.outcome))}`:''}`;const term=$('#search').value.toLowerCase(),status=$('#outcome').value;let rows=t.records.filter(r=>{const c=D.cases[r[0]],o=D.states[r[1]],why=D.reasons[r[2]];return(!status||o===status)&&(!term||[c.id,c.title,why].join(' ').toLowerCase().includes(term))});$('#cases').innerHTML=rows.map(r=>{const c=D.cases[r[0]],o=D.states[r[1]];return`<tr><td><b>${e(c.id)}</b> <small>${e(c.priority)}</small><br>${e(c.title)}</td><td><span class="badge ${o}">${e(outcomeLabel(o))}</span></td><td class="layer">${e(D.layers[r[3]])}</td><td class="reason">${e(D.reasons[r[2]])}</td><td class="num">${r[4]}</td></tr>`}).join('');$('#shown').textContent=`${rows.length} of ${t.records.length} catalog cases shown.`}
$('#jdk').onchange=matrix;$('#server').onchange=matrix;$('#outcome').onchange=cases;$('#search').oninput=cases;$('#source').textContent=`Apache-2.0 · Client source tree SHA-256 ${D.client_worktree_sha256}`;$('#blocked-reasons').innerHTML=(D.blocked_reasons||[]).map(b=>`<li>${e(b.reason)} (${b.count} tuples)</li>`).join('');$('#jdk').value='25';selected=D.tuples.findIndex(t=>t.server==='pykmip'&&t.jdk===25);matrix();
</script></body></html>'''.replace('JDK_TEXT', jdk_text).replace('CASECOUNT', str(len(data['cases']))).replace('CONTROLLED', controlled).replace(
    'DATA', json.dumps(data, separators=(',', ':')).replace('<', r'\u003c'))
(DIR / 'overview.html').write_text(licensed_html(html))

policy_rows = []
policy_titles = {'AUTH-01': 'Grant/revoke', 'AUTH-02': 'Get/Locate'}
policy_names = {'pykmip': 'PyKMIP'}
for policy in data['policy_coverage']:
    outcomes = policy['outcomes']
    descriptions = []
    for outcome, label in [('PASS', 'passed'), ('FAIL_SERVER', 'unconfirmed peer observations')]:
        if outcomes.get(outcome):
            descriptions.append(f'{outcomes[outcome]} {label}')
    policy_rows.append(
        f'<tr><td><b>{escape(policy["test_id"])}</b><br>{policy_titles[policy["test_id"]]}<br><span class="covered">Covered</span></td>'
        f'<td>{escape(", ".join(policy_names[s] for s in policy["supporting_fixtures"]))}</td>'
        f'<td><b>{policy["executed_tuples"]} runs</b><br>{escape("; ".join(descriptions))}</td></tr>')
policy_html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KMIP policy coverage</title><style>
body{margin:0;font:14px/1.5 system-ui,sans-serif;color:var(--foreground,#182b39);background:transparent}p{margin:0 0 16px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;padding:12px 10px 12px 0;border-bottom:1px solid var(--border,#dce4eb)}th{font-size:11px;text-transform:uppercase;color:var(--muted-foreground,#526a79)}td:first-child{white-space:nowrap}.covered{color:var(--success,#127047)}.note{margin:16px 0 0;color:var(--muted-foreground,#526a79);font-size:12px}a{color:var(--info,#185c9b)}@media(max-width:500px){th,td{padding-right:8px;font-size:12px}}
</style></head><body><p><b>Every policy case with a supporting fixture is covered.</b></p><table><thead><tr><th>Case</th><th>Where exercised</th><th>Observed results</th></tr></thead><tbody>ROWS</tbody></table><p class="note">Coverage means the scenario ran on every supporting fixture and selected version/JDK tuple. Other fixture gaps do not block aggregate SDK coverage; they do not establish product-wide lack of support. Server correctness remains a separate result.</p><p class="note">Tests run, none failed: TESTS. <a href="overview.html">Full catalog and evidence</a></p></body></html>'''.replace('ROWS', ''.join(policy_rows)).replace(
    'TESTS', '; '.join(f"JDK {jdk} {sum(run for runs in modules.values() for run, _ in runs):,}"
                       for jdk, modules in data['junit'].items()))
(DIR / 'policy-coverage.html').write_text(licensed_html(policy_html))
